//! Android and iOS projects: generated by the Tauri CLI in the language
//! host's project, patched for levain, then built.

use std::path::{Path, PathBuf};

/// Android only runs executables extracted from the APK, so native libraries
/// (a runtime's port programs among them) are installed as files, not mapped
/// from it. A signed build uses the key `<env>_KEYSTORE`,
/// `<env>_KEYSTORE_PASSWORD`, `<env>_KEY_ALIAS` and `<env>_KEY_PASSWORD`
/// name, read when Gradle runs.
pub fn patch_gradle(gradle: &str, signing_env: Option<&str>) -> Result<String, String> {
    let head = "android {\n";
    let at = gradle
        .find(&format!("\n{head}"))
        .map(|i| i + 1)
        .or_else(|| gradle.starts_with(head).then_some(0))
        .ok_or("build.gradle.kts has no `android {` block")?;
    let signing = signing_env.map(|env| {
        format!(
            r#"    signingConfigs {{
        create("release") {{
            storeFile = file(System.getenv("{env}_KEYSTORE"))
            storePassword = System.getenv("{env}_KEYSTORE_PASSWORD")
            keyAlias = System.getenv("{env}_KEY_ALIAS")
            keyPassword = System.getenv("{env}_KEY_PASSWORD")
        }}
    }}
"#
        )
    });
    let mut out = String::with_capacity(gradle.len() + 512);
    out.push_str(&gradle[..at + head.len()]);
    out.push_str("    packaging { jniLibs { useLegacyPackaging = true } }\n");
    out.push_str(signing.as_deref().unwrap_or(""));
    out.push_str(&gradle[at + head.len()..]);
    if signing_env.is_some() {
        let release = "getByName(\"release\") {\n";
        let at = out
            .find(release)
            .ok_or("build.gradle.kts has no release build type")?
            + release.len();
        out.insert_str(
            at,
            "            signingConfig = signingConfigs.getByName(\"release\")\n",
        );
    }
    Ok(out)
}

/// Adds linker flags to the Xcode project's build settings, and keeps global
/// symbols when an archived build is stripped (a runtime may look its own
/// symbols up with `dlsym`).
pub fn patch_xcodegen(yml: &str, ldflags: &str) -> Result<String, String> {
    let at = "        ENABLE_BITCODE: false\n";
    if !yml.contains(at) {
        return Err("project.yml has no build settings to add the linker flags to".into());
    }
    let flags =
        format!("        OTHER_LDFLAGS: $(inherited) {ldflags}\n        STRIP_STYLE: non-global\n");
    Ok(yml.replacen(at, &format!("{at}{flags}"), 1))
}

/// The mobile platforms the Tauri CLI generates projects for.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Platform {
    Android,
    Ios,
}

impl Platform {
    pub fn parse(name: &str) -> Result<Self, String> {
        match name {
            "android" => Ok(Self::Android),
            "ios" => Ok(Self::Ios),
            other => Err(format!("unknown platform {other} (android or ios)")),
        }
    }

    fn name(self) -> &'static str {
        match self {
            Self::Android => "android",
            Self::Ios => "ios",
        }
    }

    /// The generated project, under the Tauri project.
    pub fn gen_dir(self, project: &Path) -> PathBuf {
        project.join(match self {
            Self::Android => "gen/android",
            Self::Ios => "gen/apple",
        })
    }
}

/// Options for `init`.
#[derive(Debug, Default)]
pub struct Init {
    /// Android: sign release builds with keys from `<env>_*` variables.
    pub signing_env: Option<String>,
    /// iOS: extra linker flags for the app.
    pub ldflags: Option<String>,
}

/// Generates the platform's project afresh in `project` and patches it.
pub fn init(
    platform: Platform,
    project: &Path,
    config: &Path,
    options: &Init,
    env: &[(&str, String)],
) -> Result<(), String> {
    crate::cmd(
        project,
        "npm",
        &args(&["install", "--no-audit", "--no-fund"]),
        env,
    )?;
    let generated = platform.gen_dir(project);
    let _ = std::fs::remove_dir_all(&generated);
    crate::cmd(project, "npm", &init_args(platform, config), env)?;
    match platform {
        Platform::Android => {
            let path = generated.join("app/build.gradle.kts");
            let gradle = read(&path)?;
            write(
                &path,
                &patch_gradle(&gradle, options.signing_env.as_deref())?,
            )
        }
        Platform::Ios => {
            let Some(ldflags) = &options.ldflags else {
                return Ok(());
            };
            let path = generated.join("project.yml");
            write(&path, &patch_xcodegen(&read(&path)?, ldflags)?)?;
            // `ios init` generated the Xcode project before the patch; again
            // with it.
            crate::cmd(&generated, "xcodegen", &args(&["generate"]), &[])
        }
    }
}

pub fn init_args(platform: Platform, config: &Path) -> Vec<String> {
    let mut out = args(&[
        "run",
        "tauri",
        "--",
        platform.name(),
        "init",
        "--ci",
        "--config",
    ]);
    out.push(config.display().to_string());
    out
}

pub fn build_args(platform: Platform, config: &Path, extra: &[String]) -> Vec<String> {
    let mut out = args(&[
        "run",
        "tauri",
        "--",
        platform.name(),
        "build",
        "--ci",
        "--config",
    ]);
    out.push(config.display().to_string());
    out.extend(extra.iter().cloned());
    out
}

/// Builds the generated project (`extra` goes to the Tauri CLI) and copies
/// each `<ext>` product it made to `<out>/<name>.<ext>`.
pub fn build(
    platform: Platform,
    project: &Path,
    config: &Path,
    extra: &[String],
    products: &[(String, PathBuf)],
    env: &[(&str, String)],
) -> Result<(), String> {
    crate::cmd(project, "npm", &build_args(platform, config, extra), env)?;
    let outputs = match platform {
        Platform::Android => platform.gen_dir(project).join("app/build/outputs"),
        Platform::Ios => platform.gen_dir(project).join("build"),
    };
    for (ext, to) in products {
        let built = find_ext(&outputs, ext)
            .ok_or_else(|| format!("no .{ext} under {}", outputs.display()))?;
        copy_all(&built, to)?;
        eprintln!("* built {}", to.display());
    }
    Ok(())
}

/// The first file or bundle directory (`.app`) named `*.<ext>` under `dir`.
pub fn find_ext(dir: &Path, ext: &str) -> Option<PathBuf> {
    let mut entries: Vec<_> = std::fs::read_dir(dir)
        .ok()?
        .flatten()
        .map(|e| e.path())
        .collect();
    entries.sort();
    for path in &entries {
        if path.extension().is_some_and(|e| e == ext) {
            return Some(path.clone());
        }
    }
    entries
        .iter()
        .filter(|p| p.is_dir())
        .find_map(|p| find_ext(p, ext))
}

fn copy_all(from: &Path, to: &Path) -> Result<(), String> {
    if to.is_dir() {
        std::fs::remove_dir_all(to).map_err(|e| e.to_string())?;
    } else {
        let _ = std::fs::remove_file(to);
    }
    if let Some(parent) = to.parent() {
        std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
    }
    if from.is_dir() {
        std::fs::create_dir_all(to).map_err(|e| e.to_string())?;
        for entry in std::fs::read_dir(from)
            .map_err(|e| e.to_string())?
            .flatten()
        {
            copy_all(&entry.path(), &to.join(entry.file_name()))?;
        }
        Ok(())
    } else {
        std::fs::copy(from, to)
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
}

fn args(list: &[&str]) -> Vec<String> {
    list.iter().map(|s| s.to_string()).collect()
}

fn read(path: &Path) -> Result<String, String> {
    std::fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))
}

fn write(path: &Path, body: &str) -> Result<(), String> {
    std::fs::write(path, body).map_err(|e| format!("{}: {e}", path.display()))
}

#[cfg(test)]
mod tests {
    use super::*;

    const GRADLE: &str = "plugins {\n}\n\nandroid {\n    compileSdk = 34\n    buildTypes {\n        getByName(\"release\") {\n            isMinifyEnabled = true\n        }\n    }\n}\n";

    #[test]
    fn unsigned_gradle_only_installs_native_libraries() {
        let out = patch_gradle(GRADLE, None).unwrap();
        assert!(out.contains(
            "android {\n    packaging { jniLibs { useLegacyPackaging = true } }\n    compileSdk"
        ));
        assert!(!out.contains("signingConfig"));
    }

    #[test]
    fn signed_gradle_reads_the_key_from_the_environment() {
        let out = patch_gradle(GRADLE, Some("EXAMPLE_ANDROID")).unwrap();
        assert!(out.contains(r#"storeFile = file(System.getenv("EXAMPLE_ANDROID_KEYSTORE"))"#));
        assert!(out.contains(r#"keyAlias = System.getenv("EXAMPLE_ANDROID_KEY_ALIAS")"#));
        assert!(out.contains(
            "getByName(\"release\") {\n            signingConfig = signingConfigs.getByName(\"release\")\n            isMinifyEnabled"
        ));
    }

    #[test]
    fn gradle_without_an_android_block_is_refused() {
        assert!(patch_gradle("plugins {}\n", None).is_err());
    }

    #[test]
    fn xcodegen_gets_the_linker_flags_once() {
        let yml =
            "settings:\n  base:\n        ENABLE_BITCODE: false\n        ENABLE_BITCODE: false\n";
        let out = patch_xcodegen(yml, "-lc++").unwrap();
        assert_eq!(
            out,
            "settings:\n  base:\n        ENABLE_BITCODE: false\n        OTHER_LDFLAGS: $(inherited) -lc++\n        STRIP_STYLE: non-global\n        ENABLE_BITCODE: false\n"
        );
        assert!(patch_xcodegen("x: 1\n", "-lc++").is_err());
    }

    #[test]
    fn tauri_cli_arguments() {
        let config = Path::new("c.json");
        assert_eq!(
            init_args(Platform::Android, config).join(" "),
            "run tauri -- android init --ci --config c.json"
        );
        assert_eq!(
            build_args(
                Platform::Ios,
                config,
                &["--target".into(), "aarch64".into()]
            )
            .join(" "),
            "run tauri -- ios build --ci --config c.json --target aarch64"
        );
        assert!(Platform::parse("web").is_err());
    }

    #[test]
    fn finds_products_files_or_bundles() {
        let tmp = tempfile::tempdir().unwrap();
        let apk = tmp.path().join("apk/universal/release/app.apk");
        std::fs::create_dir_all(apk.parent().unwrap()).unwrap();
        std::fs::write(&apk, "apk").unwrap();
        let app = tmp.path().join("x/Counter.app");
        std::fs::create_dir_all(&app).unwrap();
        std::fs::write(app.join("Info.plist"), "plist").unwrap();

        assert_eq!(find_ext(tmp.path(), "apk"), Some(apk));
        assert_eq!(find_ext(tmp.path(), "app"), Some(app.clone()));
        assert_eq!(find_ext(tmp.path(), "aab"), None);

        let to = tmp.path().join("out/counter.app");
        copy_all(&app, &to).unwrap();
        assert_eq!(std::fs::read(to.join("Info.plist")).unwrap(), b"plist");
    }
}
